        System.out.println("### rc=" + rc);
        System.exit(rc);
    }

    static PhaseOrder[] throughChecker(PhaseOrder[] order) {
        int n = Arrays.asList(order).indexOf(PhaseOrder.TYPECHECK);
        if (n < 0) throw new RuntimeException("no TYPECHECK in the phase order");
